find:
.surface {
  composes: pk-panel from global;
  --accent-ink: var(--pk-lime-ink);
  --accent-on: var(--pk-lime-edge);
  --accent-soft: var(--pk-state-good-bg);

  overflow: hidden;
}

.toneShort {
  --accent-ink: var(--pk-pink-ink);
  --accent-on: var(--pk-magenta-edge);
  --accent-soft: var(--pk-state-loss-bg);
}

.toneAsk {
  --accent-ink: var(--pk-violet-ink);
  --accent-on: var(--pk-violet-edge);
  --accent-soft: var(--pk-state-info-bg);
}

replace:
/* The surface takes one of three tones: long (the default), short and ask. Each tone is an ink,
   an edge and a tint, written per tone where it is read. The tone sits in :where() so a toned
   rule weighs what its untoned twin weighs, and the rules after it win as they did. */
.surface {
  composes: pk-panel from global;
  overflow: hidden;
}

.surfaceMode {
  color: var(--pk-lime-ink);
}

:where(.toneShort) .surfaceMode {
  color: var(--pk-pink-ink);
}

:where(.toneAsk) .surfaceMode {
  color: var(--pk-violet-ink);
}

.rowLevelOn .rowPrice {
  color: var(--pk-lime-ink);
}

:where(.toneShort) .rowLevelOn .rowPrice {
  color: var(--pk-pink-ink);
}

:where(.toneAsk) .rowLevelOn .rowPrice {
  color: var(--pk-violet-ink);
}

.cell[data-lit] {
  background: var(--pk-state-good-bg);
}

:where(.toneShort) .cell[data-lit] {
  background: var(--pk-state-loss-bg);
}

:where(.toneAsk) .cell[data-lit] {
  background: var(--pk-state-info-bg);
}

.cell[data-on] {
  background: var(--pk-lime-edge);
}

:where(.toneShort) .cell[data-on] {
  background: var(--pk-magenta-edge);
}

:where(.toneAsk) .cell[data-on] {
  background: var(--pk-violet-edge);
}

  letter-spacing: 0.1em;
  color: var(--pk-lime-ink);
}

:where(.toneShort) .cellPill {
  border-color: var(--pk-magenta-edge);
  color: var(--pk-pink-ink);
}

:where(.toneAsk) .cellPill {
  border-color: var(--pk-violet-edge);
  color: var(--pk-violet-ink);
}

.column[data-on] .columnLabel {
  color: var(--pk-lime-ink);
}

:where(.toneShort) .column[data-on] .columnLabel {
  color: var(--pk-pink-ink);
}

:where(.toneAsk) .column[data-on] .columnLabel {
  color: var(--pk-violet-ink);
}
